import React from 'react'
import {MainWrapper,BackgroundContainer,TextContainer} from './styles';
import bgPrincipalmob from '../../../assets/images/bg-principal-mob.png';
import Input from '../../../components/Input';


const Main = () =>{
    return(
        <MainWrapper>
            < BackgroundContainer image={bgPrincipalmob } />
            <TextContainer>
            <h1 className='principal-title'>Finding the key for your home.</h1>
            <p className='subtitle'>Discover  real estate, new homes, shop mortgages, find property records & take virtual tours of houses,
                condos & apartments</p>
            </TextContainer>
            <Input />
        </MainWrapper>


      
    )
}

export default Main
